import re
lines = open('/app/resources/treasury_bulletin_1953_03.txt').readlines()

# Find all maturity dates in treasury bills section
in_bills = False
for i, line in enumerate(lines):
    if 'Treasury Bills' in line and 'Taxable' in line and 'Table' in line:
        in_bills = True
    if in_bills and 'Footnote' in line:
        break
    if in_bills:
        # Find maturity dates (format like MM/DD/YY)
        matches = re.findall(r'\|\s*(\d{1,2}/\d{1,2}/53)\s*\|', line)
        if matches:
            print(f'{i}: {line.strip()[:100]} -> {matches}')
"

