import json
data = json.load(open('/app/resources/treasury_bulletin_1953_03.json'))

# Find any tables in the JSON
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'table' in k.lower() or 'treasury' in k.lower() or 'bill' in k.lower():
                print(f'{path}.{k}')
            find_tables(v, f'{path}.{k}')
    elif isinstance(obj, list) and len(obj) > 0:
        find_tables(obj[0], f'{path}[0]')

find_tables(data)
